using System;using System.Collections.Generic;using System.Linq;using System.Xml.Linq;using Citograph.Word;
class EndNoteParserChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static string Record(string number,string title,string doi,string type="Journal Article",string typeId="17"){return "<record><rec-number>"+number+"</rec-number><foreign-keys><key app=\"EN\" db-id=\"synthetic-db\">"+number+"</key></foreign-keys><ref-type name=\""+type+"\">"+typeId+"</ref-type><contributors><authors><author>García, Ana</author><author>Research Group,</author></authors></contributors><titles><title>"+title+"</title><secondary-title>Synthetic Journal</secondary-title></titles><dates><year>2024</year></dates><volume>7</volume><number>2</number><pages>12-20</pages><publisher>Example Press</publisher><electronic-resource-num>"+doi+"</electronic-resource-num><abstract>Text &amp; detail.</abstract><keywords><keyword>Evidence</keyword></keywords><urls><web-urls><url>https://example.org</url></web-urls></urls></record>";}
 static string Field(string inner){return " ADDIN EN.CITE <EndNote>"+inner+"</EndNote> \\* MERGEFORMAT ";}
 static string Cite(string record,string options=""){return "<Cite><Author>García</Author><Year>2024</Year><RecNum>1</RecNum>"+options+record+"</Cite>";}
 static void Rejected(string code){bool rejected=false;try{EndNoteParser.Parse(code);}catch{rejected=true;}Check(rejected,"Unsafe or incompatible input was accepted.");}
 static int Main(string[] args){try{string test=args[0];
  if(test=="metadata"){var s=EndNoteParser.Parse(Field(Cite(Record("1","Evidence &amp; <style face=\"italic\">science</style>","https://doi.org/10.5555/SYNTH."))))[0];Check(Data.Text(s.reference,"title")=="Evidence & science","Rich title was not flattened.");Check(Data.Text(s.reference,"DOI")=="10.5555/synth","DOI was not normalized.");Check(Data.Authors(s.reference)=="Ana García; Research Group"&&Data.Year(s.reference)=="2024","Authors or date lost.");Check(Data.Text(s.reference,"page")=="12-20"&&Data.Text(s.reference,"container-title")=="Synthetic Journal","Publication metadata lost.");Check(s.database=="synthetic-db","Database scope lost.");}
  else if(test=="options"){var s=EndNoteParser.Parse(Field(Cite(Record("1","Test",""),"<Prefix>see </Prefix><Suffix>, emphasis added</Suffix><Pages>12–14</Pages><ExcludeAuth>1</ExcludeAuth>")))[0];Check(s.item.prefix=="see "&&s.item.suffix==", emphasis added"&&s.item.locator=="12–14"&&s.item.suppressAuthor,"Citation options lost.");}
  else if(test=="groups"){var sources=EndNoteParser.Parse(Field(Cite(Record("1","First","10.5555/one"))+Cite(Record("1","Second","10.5555/two"))));Check(sources.Count==2&&sources[0].item.id!=sources[1].item.id,"Record numbers from different libraries collided.");var again=EndNoteParser.Parse(Field(Cite(Record("99","First","10.5555/one"))))[0];Check(again.item.id==sources[0].item.id,"Identity depended on record number.");}
  else if(test=="types"){Check(Data.Text(EndNoteParser.Parse(Field(Cite(Record("1","Book","","Book","6"))))[0].reference,"type")=="book","Book was treated as journal.");Check(Data.Text(EndNoteParser.Reference(XElement.Parse("<record><ref-type>27</ref-type><titles><title>Report</title></titles></record>")),"type")=="report","Numeric report mapping failed.");}
  else if(test=="partial"){var s=EndNoteParser.Parse(Field(Cite("")))[0];Check(s.reference==null&&s.number=="1"&&s.author=="García"&&s.year=="2024","Incomplete source was invented or cannot be resolved.");}
  else if(test=="xml"){Rejected("ADDIN EN.CITE <EndNote><Cite></EndNote>");Rejected("ADDIN EN.CITE <!DOCTYPE EndNote [<!ENTITY x SYSTEM 'file:///C:/private'>]><EndNote><Cite>&x;</Cite></EndNote>");Rejected("ADDIN EN.CITE "+new string('x',16000001));}
  else if(test=="unsupported"){Rejected(Field(Cite(Record("1","Test",""),"<ExcludeYear>1</ExcludeYear>")));Rejected(Field(Cite(Record("1","Test",""),"<CustomDisplay>unknown</CustomDisplay>")));Rejected("ADDIN EN.CITE.DATA <EndNote><Cite/></EndNote>");}
  else if(test=="limits"){Rejected(Field(""));Rejected(Field(string.Concat(Enumerable.Repeat(Cite(Record("1","Test","")),101))));}
  else throw new Exception("Unknown check.");Console.WriteLine("PASS "+test);return 0;
 }catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
}
